import 'package:bonfire/bonfire.dart';
import 'package:bonfire/map/spritefusion/model/spritefucion_map.dart';

/// Level 2 - The Molten Depths.
///
/// A lava dungeon loaded directly from the SpriteFusion JSON asset
/// (`assets/images/molten_depths/map.json`), which is generated by
/// `tool/generate_molten_depths.py`. Lava is a solid layer, so it blocks
/// the player like a wall.
WorldMap buildMoltenDepthsMap() {
  return WorldMapBySpritefusion(
    WorldMapReader.fromAsset<SpritefusionMap>('molten_depths/map.json'),
  );
}
